GROUPS.splice(1,0,['Wireless workbench',[['mcs','Wi-Fi MCS explorer','MCS'],['fspl','Free-space path loss','dB'],['power','RF power & EIRP','RF'],['airtime','Airtime budget','AT'],['fresnel','Fresnel clearance','LOS'],['cwnp','CWNP study paths','CW'],['wifi-practice','Wireless practice labs','LAB']]]);
const MCS_ROWS=[['BPSK',1,1/2],['QPSK',2,1/2],['QPSK',2,3/4],['16-QAM',4,1/2],['16-QAM',4,3/4],['64-QAM',6,2/3],['64-QAM',6,3/4],['64-QAM',6,5/6],['256-QAM',8,3/4],['256-QAM',8,5/6],['1024-QAM',10,3/4],['1024-QAM',10,5/6]];
const MCS_CODES=['1/2','1/2','3/4','1/2','3/4','2/3','3/4','5/6','3/4','5/6','3/4','5/6','3/4','5/6'];
const MCS_STANDARDS={n:{name:'Wi-Fi 4 · 802.11n',widths:[20,40],gis:[0.8,0.4],max:7,streams:4,tones:{20:52,40:108},symbol:3.2},ac:{name:'Wi-Fi 5 · 802.11ac',widths:[20,40,80,160],gis:[0.8,0.4],max:9,streams:4,tones:{20:52,40:108,80:234,160:468},symbol:3.2},ax:{name:'Wi-Fi 6/6E · 802.11ax',widths:[20,40,80,160],gis:[0.8,1.6,3.2],max:11,streams:8,tones:{20:234,40:468,80:980,160:1960},symbol:12.8},be:{name:'Wi-Fi 7 · 802.11be',widths:[20,40,80,160,320],gis:[0.8,1.6,3.2],max:13,streams:8,tones:{20:234,40:468,80:980,160:1960,320:3920},symbol:12.8}};
function mcsRate(standard,width,nss,gi,mcs){const spec=MCS_STANDARDS[standard];if(!spec||!spec.widths.includes(width)||!spec.gis.includes(gi)||nss<1||nss>spec.streams||!Number.isInteger(nss)||mcs<0||mcs>spec.max||!Number.isInteger(mcs))return null;if(standard==='ac'&&((width===20&&mcs===9&&nss!==3)||(width===80&&mcs===6&&nss===3)||(width===160&&mcs===9&&nss===3)))return null;const r=[...MCS_ROWS,['4096-QAM',12,3/4],['4096-QAM',12,5/6]][mcs];return spec.tones[width]*r[1]*r[2]*nss/(spec.symbol+gi);}
function mcsExplorer(){let visible=[];const standards=[['ax',MCS_STANDARDS.ax.name],['n',MCS_STANDARDS.n.name],['ac',MCS_STANDARDS.ac.name],['be',MCS_STANDARDS.be.name]];$('surface').innerHTML=card('MCS rate explorer','<p>Compare modulation, coding and nominal PHY rates across Wi-Fi generations. Select a rate to see its calculation. HT uses combined MCS indices 0–31; VHT, HE and EHT use an MCS index with a separate stream count.</p><p>Wi-Fi 4/5 scope: 1–4 streams. Wi-Fi 6/7 scope: 1–8 streams. Full-band, unpunctured rates; no small OFDMA RUs, MLO summation, EHT MCS 14/15 or unequal-modulation HT modes.</p>')+card('Filter the table','<div class="fields">'+select('mcs-standard','Wi-Fi standard',standards)+select('mcs-width','Channel width (MHz)',['20','40','80','160'])+select('mcs-nss','Spatial streams',['1','2','3','4','5','6','7','8'])+select('mcs-gi','Guard interval (µs)',['0.8','1.6','3.2'])+input('mcs-search','Search MCS / modulation / rate','','search')+'</div><div class="actions">'+btn('mcs-reset','Reset filters')+btn('mcs-csv','Export filtered CSV')+btn('mcs-print','Print / save PDF')+'</div>'+out())+card('Selected rate',out('mcs-detail'))+hint('PHY rate is not application throughput. Unsupported combinations appear as — rather than invented rates.')+card('References and credit','<p>Rate-table interaction inspired by <a href="https://semfionetworks.com/tools/mcs-index" target="_blank" rel="noopener">SemFio Networks’ MCS index</a>. Calculations are generated locally in this workshop.</p><p><a href="https://www.cisco.com/c/en/us/support/docs/wireless-mobility/wireless-lan-wlan/212892-802-11ac-wireless-throughput-testing-and.html" target="_blank" rel="noopener">Cisco Wi-Fi 6/7 rate reference</a> · <a href="https://community.cisco.com/t5/networking-knowledge-base/802-11ac-mcs-rates/ta-p/3155920" target="_blank" rel="noopener">Cisco VHT rate tables</a></p>');
const detail=i=>{const row=visible[i],spec=MCS_STANDARDS[row.standard];$('mcs-detail').innerHTML=stats([['Standard',spec.name],['MCS',row.index],['Modulation',row.mod],['PHY rate',row.rate.toFixed(1)+' Mbps']])+hint(spec.tones[row.width]+' data subcarriers × '+row.bits+' bits × '+row.code+' coding × '+row.nss+' streams ÷ ('+spec.symbol+' + '+row.gi+') µs = '+row.rate.toFixed(1)+' Mbps.');};
const run=()=>{const standard=$('mcs-standard').value,spec=MCS_STANDARDS[standard],width=+$('mcs-width').value,nss=+$('mcs-nss').value,gi=+$('mcs-gi').value,query=$('mcs-search').value.trim().toLowerCase();visible=[];const rows=[];for(let mcs=0;mcs<=spec.max;mcs++){const r=[...MCS_ROWS,['4096-QAM',12,3/4],['4096-QAM',12,5/6]][mcs],rate=mcsRate(standard,width,nss,gi,mcs),index=standard==='n'?(nss-1)*8+mcs:mcs,code=MCS_CODES[mcs];if(query&&!`${index} ${r[0]} ${code} ${rate===null?'unsupported':rate.toFixed(1)}`.toLowerCase().includes(query))continue;const i=visible.length;visible.push({standard,width,nss,gi,index,mod:r[0],bits:r[1],code,rate});rows.push([index,nss,r[0],code,rate===null?'— (unsupported)':'<button class="mcs-rate" data-rate="'+i+'" aria-label="Explain MCS '+index+' rate '+rate.toFixed(1)+' Mbps">'+rate.toFixed(1)+'</button>']);}$('output').innerHTML=table(['MCS','Streams','Modulation','Coding','PHY Mbps'],rows)+hint(rows.length+' rows · '+width+' MHz · '+gi+' µs GI');$('mcs-detail').innerHTML='<p>Select a supported rate to inspect the calculation.</p>';$('output').querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>detail(+b.dataset.rate));};
const sync=()=>{const spec=MCS_STANDARDS[$('mcs-standard').value];for(const [id,values]of [['mcs-width',spec.widths],['mcs-nss',Array.from({length:spec.streams},(_,i)=>i+1)],['mcs-gi',spec.gis]]){const old=$(id).value;$(id).innerHTML=values.map(v=>'<option value="'+v+'">'+v+'</option>').join('');$(id).value=values.map(String).includes(old)?old:String(values[0]);}run();};$('mcs-standard').onchange=sync;['mcs-width','mcs-nss','mcs-gi'].forEach(id=>$(id).onchange=run);$('mcs-search').oninput=run;action('mcs-reset',()=>{$('mcs-standard').value='ax';$('mcs-width').value='20';$('mcs-nss').value='1';$('mcs-gi').value='0.8';$('mcs-search').value='';sync();});action('mcs-csv',()=>download('wifi-mcs-rates.csv','Standard,MCS,Streams,Width MHz,GI us,Modulation,Coding,PHY Mbps\n'+visible.map(r=>[r.standard,r.index,r.nss,r.width,r.gi,r.mod,r.code,r.rate===null?'Unsupported':r.rate.toFixed(1)].join(',')).join('\n')));action('mcs-print',()=>window.print());run();}
function finiteInput(id,minimum=0){const v=Number($(id).value);if(!$(id).value.trim()||!Number.isFinite(v)||v<minimum)throw Error('Enter a valid value for '+$(id).parentElement.textContent.trim()+'.');return v;}
function wirelessRender(id){if(!['mcs','fspl','power','airtime','fresnel','cwnp','wifi-practice'].includes(id))return false;
 if(id==='mcs')mcsExplorer();
 if(id==='wifi-practice')wirelessPractice();
 if(id==='fspl')fsplWorkbench();
 if(id==='power'){$('surface').innerHTML=card('Learn · Power and antenna gain','<p>dBm represents power relative to 1 mW. dB represents a ratio. EIRP combines transmitter power, antenna gain and feeder losses; permitted limits depend on location, band and operating mode.</p>')+card('Experiment · Power budget','<div class="fields">'+input('pw-t','Transmit power (dBm)',20,'number')+input('pw-g','Antenna gain (dBi)',4,'number')+input('pw-l','Feeder loss (dB)',2,'number')+'</div>'+btn('pw-run','Calculate power',true)+out())+hint('This is a calculation tool, not a regulatory-compliance checker.');const run=()=>{const t=finiteInput('pw-t',-300),g=finiteInput('pw-g',-300),l=finiteInput('pw-l');$('output').innerHTML=stats([['Transmitter power',(10**(t/10)).toFixed(3)+' mW'],['EIRP',(t+g-l).toFixed(2)+' dBm'],['EIRP power',(10**((t+g-l)/10)).toFixed(3)+' mW']]);};action('pw-run',run);run();}
 if(id==='airtime'){$('surface').innerHTML=card('Learn · Airtime is shared','<p>A slow transmission occupies more time for the same payload. This lower-bound model counts payload serialization only; it omits preambles, ACKs, contention, aggregation and retries.</p>')+card('Experiment · Offered payload','<div class="fields">'+input('at-bytes','Payload bytes',1500,'number')+input('at-rate','PHY rate (Mbps)',100,'number')+input('at-pps','Packets per second per client',100,'number')+input('at-clients','Clients',20,'number')+'</div>'+btn('at-run','Estimate airtime',true)+out());const run=()=>{const bytes=finiteInput('at-bytes',1),rate=finiteInput('at-rate',0.001),pps=finiteInput('at-pps'),clients=finiteInput('at-clients');const ms=bytes*8/(rate*1000),use=ms*pps*clients/10;$('output').innerHTML=stats([['Payload time per packet',ms.toFixed(3)+' ms'],['Offered serialization airtime',use.toFixed(1)+'%']])+hint(use>100?'Demand exceeds the modeled channel time even before overhead.':'Actual occupied airtime will be higher when overhead is included.',use>100);};action('at-run',run);run();}
 if(id==='fresnel'){$('surface').innerHTML=card('Learn · Clearance around a link','<p>The first Fresnel zone describes the region around a line-of-sight path where obstacles can affect propagation. A 60% radius is a common planning check, not a guarantee of reliable operation.</p>')+card('Experiment · Clearance at an obstacle','<div class="fields">'+input('fr-f','Frequency (GHz)',5.18,'number')+input('fr-d1','Distance from endpoint A (metres)',500,'number')+input('fr-d2','Distance from endpoint B (metres)',500,'number')+'</div>'+btn('fr-run','Calculate clearance',true)+out())+hint('This tool excludes Earth curvature, atmospheric refraction, vegetation growth and obstruction geometry.');const run=()=>{const f=finiteInput('fr-f',0.001),a=finiteInput('fr-d1',0.001),b=finiteInput('fr-d2',0.001),r=Math.sqrt(299792458/(f*1e9)*a*b/(a+b));$('output').innerHTML=stats([['First-zone radius',r.toFixed(2)+' m'],['60% of radius',(r*.6).toFixed(2)+' m'],['Total link length',(a+b).toFixed(1)+' m']]);};action('fr-run',run);run();}
 if(id==='cwnp')cwnpStudy();return true;}
const WIRELESS_LESSONS={
 CWNA:[['RF foundations','Separate amplitude, frequency and phase. Convert between dBm and milliwatts before combining antenna gain and losses.','Predict what happens to EIRP when feeder loss rises by 3 dB. Verify with the RF power tool.','power','A 3 dB additional loss reduces power to about half.'],['Propagation','Free-space loss is only a baseline. Reflection, diffraction, scattering and absorption make indoor coverage location-dependent.','Compare 2.4 and 5 GHz at the same distance using the path-loss calculator. Explain why this is not a coverage survey.','fspl','The model excludes obstacles and interference.'],['802.11 access','Stations contend for a shared medium. PHY rate is not payload throughput; contention, retries and protocol exchanges consume airtime.','Estimate payload airtime at two PHY rates and list the missing overhead.','airtime','Preambles, ACKs, interframe spacing, contention and retries are omitted.'],['Client capability','Channel width, spatial streams and supported modulation limit the usable PHY combinations. AP capability alone does not define client rate.','Use the MCS table to compare one and two streams at the same width and GI.','mcs','Nominal rate doubles in this model; useful throughput need not double.']],
 CWAP:[['Capture placement','A useful capture must observe the relevant channel and traffic direction. Record channel, width, timestamps and dropped-packet counters.','Explain what a capture with repeated SYNs but no reply cannot prove.','capture','It cannot distinguish every routing, filtering or service failure.'],['Frame analysis','Management, control and data frames serve different purposes. Correlate retry indicators, sequence numbers and acknowledgments with capture quality.','Write an evidence checklist before concluding that a station failed to acknowledge a frame.','capture','A missing observed ACK can reflect capture limitations.'],['Airtime analysis','Analyze slow rates, retries and contention together. Channel busy time does not identify which traffic or interference caused it.','Calculate a payload-only lower bound, then explain why channel utilization can be higher.','airtime','MAC exchanges and retransmissions add occupied time.'],['Roaming investigation','Follow discovery, authentication, association and security exchanges across the old and new AP. Align capture clocks before estimating interruption.','Build a timeline with an observed frame, timestamp and confidence level for each step.','capture','Evidence from one channel may miss part of the transition.']],
 CWDP:[['Requirements first','Define applications, client types, capacity, coverage, roaming and availability before choosing AP placement.','Create a change/design plan that includes measurable post-deployment acceptance criteria.','automation','Design acceptance should test representative clients and workloads.'],['Capacity planning','Size a design around airtime demand and contention rather than an advertised peak rate alone.','Vary clients and offered packets in the airtime model. Identify its optimistic assumptions.','airtime','The model omits overhead and does not predict user experience.'],['RF design','Channel reuse, power balance, antenna pattern and obstacles influence the design. Client return-path capability matters.','Compare an AP link budget with the assumptions needed for the client uplink.','wifi-rf','A strong downlink does not establish a strong uplink.'],['Validation survey','Use post-deployment measurements to test design intent. Record actual client capability, retries, signal quality and application performance.','Write a repeatable acceptance test with normal and failure conditions.','automation','A survey validates assumptions; it does not replace requirements.']],
 CWSP:[['Identity and access','Separate authentication, authorization and encryption. An authenticated identity still needs the intended access policy.','Write tests for successful authentication, rejected credentials and correct network placement.','automation','Test both permitted and denied access.'],['Enterprise authentication','802.1X and EAP involve the supplicant, authenticator and authentication server. Certificate validation affects whether a client trusts the server.','Document the certificate chain, expected server identity and failure evidence.','automation','Do not disable validation to hide a trust failure.'],['Key establishment','Authentication and key establishment are related but distinct. Observe the security exchange without exposing captured credentials or key material.','Define where to capture and what evidence confirms completion.','capture','A capture may show exchanges without proving every endpoint state.'],['Security operations','Segment clients intentionally, protect management and verify changes in stages. Threat detection needs context to avoid treating every anomaly as an attack.','Prepare a rollback-aware security policy change plan.','automation','Pre-checks, post-checks and stop conditions should be explicit.']],
 CWNE:[['Evidence portfolio','Expert development includes documented design, implementation, analysis and security decisions. Maintain evidence that explains tradeoffs and outcomes.','Create a project outline containing requirements, decisions, validation and lessons learned.','automation','The portfolio should make reasoning and evidence reviewable.'],['Integrated troubleshooting','Combine RF, MAC, IP, application and security evidence. A symptom at one layer can be caused by another layer.','Build competing hypotheses for a connection timeout and specify the next discriminating test.','capture','Choose a test that separates hypotheses rather than repeating the symptom.'],['Design defense','Explain capacity, resilience, security and operational tradeoffs in a proposed WLAN. Include limitations in the models you use.','Defend an RF design using link-budget and airtime assumptions, then list measurements needed.','wifi-rf','Modeled results must be checked against deployment evidence.'],['Development roadmap','CWNE has an application process; it is not presented here as a standalone exam-preparation course. Confirm current prerequisites and submission requirements with CWNP.','Review the official CWNE page and create a personal evidence checklist.','automation','Use CWNP for current eligibility and application rules.']]
};
function cwnpStudy(){let track='CWNA',index=0;const names=Object.keys(WIRELESS_LESSONS);$('surface').innerHTML=card('Original wireless study notes','<p>Concise lessons and practical exercises for CWNA, CWAP, CWDP, CWSP and CWNE development. This independent material is not official CWNP courseware, a complete exam syllabus or a collection of exam questions.</p>'+select('cw-track','Study path',names)+'<div class="actions" id="cw-modules"></div>')+card('Lesson and practice',out())+card('Official resources','<p><a href="https://www.cwnp.com/it-certifications/" target="_blank" rel="noopener">CWNP certification paths</a> · <a href="https://lms.cwnp.com/" target="_blank" rel="noopener">Official learning materials</a> · <a href="https://www.cwnp.com/certifications/cwne" target="_blank" rel="noopener">CWNE requirements</a></p>');const draw=()=>{const lesson=WIRELESS_LESSONS[track][index];$('cw-modules').innerHTML=WIRELESS_LESSONS[track].map((l,i)=>'<button data-cw="'+i+'" class="'+(i===index?'primary':'')+'">'+esc(l[0])+'</button>').join('');$('output').innerHTML='<div class="eyebrow">'+track+' · Module '+(index+1)+' / 4</div><h3>'+esc(lesson[0])+'</h3><p>'+esc(lesson[1])+'</p><h3>Practice task</h3><p>'+esc(lesson[2])+'</p>'+btn('cw-lab','Practice: '+esc(lesson[0]),true)+'<details class="lesson"><summary>Review your explanation</summary><p>'+esc(lesson[4])+'</p></details>';action('cw-lab',()=>{wirelessPracticeSelection={track,index};navigate('wifi-practice');});$('cw-modules').querySelectorAll('[data-cw]').forEach(b=>b.onclick=()=>{index=+b.dataset.cw;draw();});};$('cw-track').onchange=()=>{track=$('cw-track').value;index=0;draw();};draw();}
// Each study module has its own diagnostic exercise, not a generic destination.
const WIRELESS_PRACTICE={
CWNA:[
['A radio transmits at 20 dBm with 4 dBi antenna gain. Feeder loss changes from 2 to 5 dB. What is the new EIRP?', ['19 dBm','22 dBm','29 dBm'],0,'20 + 4 − 5 = 19 dBm. The previous EIRP was 22 dBm; the 3 dB reduction roughly halves radiated power.','power'],
['At equal distance, compare free-space loss at 2.4 GHz and 4.8 GHz. Which conclusion follows?', ['Coverage radius must halve indoors','Modeled loss rises by about 6 dB','The higher frequency has less free-space loss'],1,'20 log10(4.8/2.4) is about 6.02 dB. Indoor coverage also depends on obstacles, antennas and receiver requirements.','fspl'],
['Two stations finish DIFS with backoff counters 2 and 5. One idle slot passes, then another station transmits. What happens to their remaining counters?', ['Both counters reset to zero','Both continue counting while the medium is busy','They freeze at 1 and 4, then resume after the required idle interval'],2,'In this simplified DCF sequence, backoff decrements only in eligible idle slots and freezes while the medium is busy. Airtime is a separate capacity calculation, not a DCF simulator.',null],
['An AP supports four streams but a client supports two. At fixed MCS, width and GI, which stream count limits their link?', ['Two','Four','Six'],0,'The negotiated link is limited by capabilities at both endpoints. AP maximum rate is not the client rate.','mcs']
],
CWAP:[
['The client is on channel 36; the capture radio stayed on channel 149. No association frames were observed. What should you do first?', ['Conclude that the AP rejected the client','Capture on the client’s channel with suitable placement','Increase AP transmit power'],1,'The capture did not observe the relevant channel. Correct placement and channel selection before drawing conclusions from missing frames.',null],
['A capture shows a data MPDU and another MPDU with the same transmitter, sequence and fragment values, now with Retry set. What does that support?', ['An observed retransmission of that MPDU','Proof of a malicious duplicate','Proof the receiver never sent an ACK'],0,'Retry and sequence evidence support a retransmission. They do not prove why acknowledgment was unsuccessful or whether the monitor missed an ACK.',null],
['Twenty clients each send 100 packets/s of 1500 bytes at 100 Mbps. What is their payload-only serialization demand?', ['2.4%','24%','240%'],1,'1500 × 8 / 100 Mbps = 0.12 ms per packet. 2000 packets/s occupy 240 ms/s, or 24%, before MAC overhead and retries.','airtime'],
['Capture A has the last old-AP data frame at 10.000 s. Capture B has the first new-AP frame at 10.080 s, but clocks are not synchronized. Can you assert an 80 ms outage?', ['Yes, timestamps always match','No; align clocks and establish application continuity evidence','No roaming occurred'],1,'Different capture clocks can create an apparent gap. Align clocks and use application/packet continuity evidence before assigning interruption duration.',null]
],
CWDP:[
['A voice WLAN requires roaming interruption below an agreed threshold. Which acceptance test best matches that requirement?', ['Count installed APs','Record maximum advertised PHY rate','Measure representative voice sessions during repeatable roaming paths'],2,'Translate the business requirement into measurable client behavior. Define the threshold and capture method before deployment.',null],
['Your payload airtime estimate is 70%. Is that enough evidence to approve a capacity design?', ['No; include overhead, retries, contention and representative-load validation','Yes; any estimate below 100% guarantees capacity','Yes; increase channel width and skip testing'],0,'Payload serialization is an optimistic lower bound. Validate busy-hour workloads, latency, loss and retry behavior.','airtime'],
['AP EIRP is 24 dBm, client EIRP is 14 dBm and path loss is 80 dB. Assume equal receive antenna gains and no other losses. Which receive powers are predicted?', ['Both −56 dBm','Client −56 dBm; AP −66 dBm','Client −66 dBm; AP −56 dBm'],1,'Downlink is 24 − 80 = −56 dBm; uplink is 14 − 80 = −66 dBm. Receiver sensitivity and actual gains still affect usable service.','wifi-rf'],
['A post-deployment survey has strong RSSI everywhere, but voice calls fail during roaming. Which result validates the design?', ['RSSI alone proves success','AP inventory proves success','Test the roaming/application acceptance criteria and investigate the failures'],2,'Validation must cover the agreed application and mobility requirements, not only signal coverage.',null]
],
CWSP:[
['802.1X succeeds for a contractor, but the client is placed in an unrestricted employee VLAN. Which control failed?', ['Authorization / network placement','RF propagation','PHY modulation'],0,'Authentication establishes an identity. Authorization determines the access that identity receives. Verify VLAN/role assignment and permitted and denied traffic.',null],
['A managed EAP-TLS client rejects the RADIUS server certificate because its name is unexpected. What is the appropriate response?', ['Disable server certificate validation','Investigate the expected server name, trust chain and certificate provisioning','Replace EAP with an open SSID'],1,'Check the configured trusted server identity, CA chain, validity and provisioning. Bypassing validation hides the failure and weakens server authentication.',null],
['A monitor sees EAP success followed by repeated four-way-handshake message 1, but no observed message 2. What is the strongest next step?', ['Declare that the PSK is definitely wrong','Declare the handshake complete','Correlate client/AP logs and a correctly placed capture to find whether message 2 was sent or received'],2,'EAP success is not completion of the four-way handshake. Missing observed message 2 can be a client, RF or capture issue. Correlate endpoint evidence. Do not expose keys.',null],
['A guest client can reach an internal management address after a policy change. What is the best test and correction sequence?', ['Verify the deny path and intended policy assignment, correct the policy, then retest guest isolation and allowed services','Ignore it because authentication succeeded','Block all wireless traffic permanently'],0,'Check segmentation and enforcement with both denied and permitted traffic. Use a staged change, stop conditions and rollback if service breaks.',null]
],
CWNE:[
['Which portfolio entry best demonstrates an engineering decision?', ['A screenshot with no context','Requirements, alternatives, chosen tradeoff, validation results and lessons learned','An AP model list only'],1,'Evidence should connect requirements, decisions and measured outcomes. This exercise is a portfolio review; official application rules remain with CWNP.',null],
['A client is associated and has an IP address. DNS queries time out, while connections to a known server IP work. What test best separates the remaining hypotheses?', ['Check DNS resolver reachability and query/response evidence','Change all AP channels immediately','Replace every client'],0,'Working IP connectivity narrows the investigation. Examine DNS configuration, reachability and query/response behavior before unrelated RF changes.',null],
['A design promises capacity based only on the AP’s maximum 4-stream PHY rate, while clients use 1 stream. What must the defense address?', ['The logo of the AP vendor','The number of switch LEDs','Client capabilities, airtime demand, contention and measured workload performance'],2,'Defend the assumptions that connect model inputs to actual clients and workload; include validation and operational tradeoffs.','mcs'],
['You are planning a CWNE application. Which source should set eligibility and submission requirements?', ['This practice quiz alone','The current official CWNP CWNE requirements and application guidance','An old forum checklist with no date'],1,'CWNE is an application-based credential. Check current official requirements and maintain an evidence checklist against them.',null]
]};
let wirelessPracticeSelection={track:'CWNA',index:0};
function wirelessPractice(){let {track,index}=wirelessPracticeSelection;if(!WIRELESS_PRACTICE[track]){track='CWNA';index=0;}const names=Object.keys(WIRELESS_PRACTICE);$('surface').innerHTML=card('Wireless diagnostic practice','<p>Original, synthetic scenarios tied to each CWNP study module. Choose an answer, inspect the reasoning and explain what evidence you would collect next. These exercises do not emulate a live WLAN or reproduce official exam questions.</p><div class="fields">'+select('wp-track','Certification path',names)+select('wp-module','Module',WIRELESS_LESSONS[track].map((l,i)=>[String(i),l[0]]))+'</div>')+card('Scenario',out('wp-scenario'))+card('Your reasoning',area('wp-notes','What evidence would you collect next?')+btn('wp-save','Download field notes'))+'<div class="actions">'+btn('wp-back','Back to this study module')+'</div>';
const draw=()=>{wirelessPracticeSelection={track,index};const lesson=WIRELESS_LESSONS[track][index],p=WIRELESS_PRACTICE[track][index];$('wp-scenario').innerHTML='<div class="eyebrow">'+track+' · '+esc(lesson[0])+'</div><h3>'+esc(p[0])+'</h3><div class="actions">'+p[1].map((answer,i)=>'<button data-wp-answer="'+i+'">'+esc(answer)+'</button>').join('')+ '</div>'+out('wp-feedback')+(p[4]?'<p>Calculation support: <button id="wp-tool">'+esc(PAGES.find(x=>x.id===p[4]).title)+' →</button></p>':'')+(track==='CWNE'&&index===3?'<p><a href="https://www.cwnp.com/certifications/cwne" target="_blank" rel="noopener">Open official CWNE requirements ↗</a></p>':'');$('wp-scenario').querySelectorAll('[data-wp-answer]').forEach(b=>b.onclick=()=>{$('wp-feedback').innerHTML=hint((+b.dataset.wpAnswer===p[2]?'Correct. ':'Reconsider your answer. ')+esc(p[3]),+b.dataset.wpAnswer!==p[2]);});if(p[4])action('wp-tool',()=>navigate(p[4]));};$('wp-track').value=track;$('wp-module').value=String(index);$('wp-track').onchange=()=>{track=$('wp-track').value;index=0;$('wp-module').innerHTML=WIRELESS_LESSONS[track].map((l,i)=>'<option value="'+i+'">'+esc(l[0])+'</option>').join('');$('wp-module').value='0';$('wp-notes').value='';draw();};$('wp-module').onchange=()=>{index=+$('wp-module').value;$('wp-notes').value='';draw();};action('wp-save',()=>download('wireless-field-notes.txt',track+' — '+WIRELESS_LESSONS[track][index][0]+'\n\n'+WIRELESS_PRACTICE[track][index][0]+'\n\nMy evidence plan:\n'+$('wp-notes').value));action('wp-back',()=>{const saved={track,index};navigate('cwnp');$('cw-track').value=saved.track;$('cw-track').onchange();$('cw-modules').querySelector('[data-cw="'+saved.index+'"]').onclick();});draw();}
function fsplValue(fMHz,dMetres){if(!Number.isFinite(fMHz)||!Number.isFinite(dMetres)||fMHz<=0||dMetres<=0)throw Error('Frequency and distance must be positive.');return 20*Math.log10(4*Math.PI*dMetres*fMHz*1e6/299792458);}
function fsplBudget(fMHz,dMetres,tx,gain,feeder,walls=[]){const free=fsplValue(fMHz,dMetres),wallLoss=walls.filter(w=>w.distance<=dMetres).reduce((n,w)=>n+w.loss,0);return {free,wallLoss,total:free+wallLoss,eirp:tx+gain-feeder,signal:tx+gain-feeder-free-wallLoss};}
function fsplWorkbench(){let walls=[],csvRows=[],chartMarkup='';const bands=[['24','2.4 GHz',2437,'#be550d'],['5','5 GHz',5500,'#2675bb'],['6','6 GHz',6195,'#8d54b5']];$('surface').innerHTML=card('Compare Wi-Fi propagation','<p>Compare loss and estimated received signal across 2.4, 5 and 6 GHz. Choose channel frequencies, set the transmitter budget and add optional flat wall losses.</p><p>Loss is shown as a positive attenuation in dB. Signal is EIRP minus total loss, assuming 0 dBi receive antenna gain.</p>')+card('Distance and display','<div class="fields">'+select('fs-unit','Distance unit',[['m','Metres'],['ft','Feet']])+input('fs-d','Distance to read',8,'number','min="0.1" step="0.1"')+input('fs-axis','Chart distance limit',30,'number','min="1" step="1"')+select('fs-mode','Chart values',[['loss','Path loss (dB)'],['signal','Received signal (dBm)']])+select('fs-scale','Distance axis',[['linear','Linear'],['log','Logarithmic']])+'</div><div class="actions">'+btn('fs-run','Calculate',true)+btn('fs-reset','Reset')+btn('fs-csv','Export CSV')+btn('fs-png','Export chart PNG')+'</div>'+out())+card('Channels and transmitter','<div class="fields">'+bands.map(([id,label,f])=>select('fs-ch-'+id,label+' channel',fsplChannels(id))+input('fs-f-'+id,label+' frequency (MHz)',f,'number','min="1" step="1"')).join('')+input('fs-tx','Transmit power (dBm)',14,'number')+input('fs-gain','Transmit antenna gain (dBi)',4,'number')+input('fs-feeder','Feeder loss (dB)',0,'number','min="0"')+'</div>'+out('fs-eirp'))+card('Optional walls','<p>Enter the distance from the transmitter and a flat attenuation per wall. The same supplied attenuation is applied to all bands; actual material loss can vary with frequency.</p><div id="fs-walls"></div>'+btn('fs-add-wall','Add wall')+out('fs-wall-note'))+card('Path loss over distance',out('fs-chart'))+card('Reference distances',out('fs-table'))+hint('Free-space, far-field model: no reflection, diffraction, multipath, body loss or receiver implementation losses. Flat wall steps are an illustrative extension, not a measured propagation model. Channel lists are frequency references, not permission to operate in a region.')+card('Formula and credit','<p>FSPL = 20 log₁₀(4πdf/c), with distance in metres and frequency in Hz. Equivalently, approximately 20 log₁₀(d km) + 20 log₁₀(f GHz) + 92.45 dB.</p><p>Workbench features inspired by <a href="https://semfionetworks.com/tools/fspl" target="_blank" rel="noopener">SemFio Networks’ free-space path-loss tool</a>. Independently implemented calculations. <a href="https://www.itu.int/rec/R-REC-P.525-5-202411-I/en" target="_blank" rel="noopener">ITU-R P.525 reference</a>.</p>');
function read(){const unit=$('fs-unit').value,factor=unit==='ft'?0.3048:1,d=finiteInput('fs-d',0.000001)*factor,max=finiteInput('fs-axis',0.000001)*factor,tx=finiteInput('fs-tx',-300),gain=finiteInput('fs-gain',-300),feeder=finiteInput('fs-feeder'),freq=bands.map(b=>finiteInput('fs-f-'+b[0],0.000001));return {unit,factor,d,max,tx,gain,feeder,freq,mode:$('fs-mode').value,log:$('fs-scale').value==='log'};}
const draw=()=>{const o=read(),results=o.freq.map(f=>fsplBudget(f,o.d,o.tx,o.gain,o.feeder,walls));$('output').innerHTML=stats(results.map((r,i)=>[bands[i][1],(o.mode==='loss'?r.total:r.signal).toFixed(2)+(o.mode==='loss'?' dB loss':' dBm')]))+hint('At '+(o.d/o.factor).toFixed(2)+' '+o.unit+' · '+walls.filter(w=>w.distance<=o.d).length+' wall(s) crossed'+(o.d>o.max?' · Read distance is beyond the chart limit.':''));const eirp=o.tx+o.gain-o.feeder;$('fs-eirp').innerHTML=stats([['EIRP',eirp.toFixed(2)+' dBm'],['EIRP power',(10**(eirp/10)).toFixed(2)+' mW']]);$('fs-wall-note').innerHTML=hint(walls.length?'Wall losses are added only at and beyond each wall’s distance.':'No walls: the loss curve is pure FSPL.');
const reference=[1,2,4,8,16,30].map(v=>v*o.factor).filter(v=>v<=o.max);const distances=[...new Set([...reference,o.d,o.max,...walls.map(w=>w.distance).filter(d=>d>0&&d<=o.max)])].sort((a,b)=>a-b);csvRows=distances.map(d=>{const rs=o.freq.map(f=>fsplBudget(f,d,o.tx,o.gain,o.feeder,walls));return [(d/o.factor).toFixed(3),o.unit,walls.filter(w=>w.distance<=d).length,...rs.flatMap(r=>[r.free.toFixed(3),r.wallLoss.toFixed(3),r.total.toFixed(3),r.signal.toFixed(3)])];});$('fs-table').innerHTML=table(['Distance ('+o.unit+')','Walls crossed',...bands.map(b=>b[1]+(o.mode==='loss'?' loss dB':' signal dBm'))],distances.map(d=>[(d/o.factor).toFixed(2),walls.filter(w=>w.distance<=d).length,...o.freq.map(f=>{const r=fsplBudget(f,d,o.tx,o.gain,o.feeder,walls);return (o.mode==='loss'?r.total:r.signal).toFixed(2);})]));chartMarkup=fsplChart(o,walls,bands);$('fs-chart').innerHTML=chartMarkup+'<p>Each distance doubling adds approximately 6.02 dB of free-space loss. Vertical steps show the supplied wall attenuation.</p>';};
const drawWalls=()=>{const factor=$('fs-unit').value==='ft'?0.3048:1,unit=$('fs-unit').value;$('fs-walls').innerHTML=walls.map((w,i)=>'<div class="fs-wall fields">'+input('fs-wall-d-'+i,'Wall '+(i+1)+' distance ('+unit+')',+(w.distance/factor).toFixed(3),'number','min="0" step="0.1"')+input('fs-wall-loss-'+i,'Attenuation (dB)',w.loss,'number','min="0" step="0.5"')+'<button data-wall-remove="'+i+'">Remove wall '+(i+1)+'</button></div>').join('');walls.forEach((w,i)=>{const update=()=>safe(()=>{w.distance=finiteInput('fs-wall-d-'+i)*factor;w.loss=finiteInput('fs-wall-loss-'+i);draw();});$('fs-wall-d-'+i).onchange=update;$('fs-wall-loss-'+i).onchange=update;});$('fs-walls').querySelectorAll('[data-wall-remove]').forEach(b=>b.onclick=()=>{walls.splice(+b.dataset.wallRemove,1);drawWalls();safe(draw);});};
let previousUnit='m';$('fs-unit').onchange=()=>safe(()=>{const next=$('fs-unit').value,oldFactor=previousUnit==='ft'?0.3048:1,newFactor=next==='ft'?0.3048:1;for(const id of ['fs-d','fs-axis'])$(id).value=+(Number($(id).value)*oldFactor/newFactor).toFixed(6);previousUnit=next;drawWalls();draw();});for(const id of ['fs-d','fs-axis','fs-mode','fs-scale','fs-tx','fs-gain','fs-feeder'])$(id).onchange=()=>safe(draw);bands.forEach(([id,,freq])=>{$('fs-ch-'+id).value=String(freq);$('fs-ch-'+id).onchange=()=>{if($('fs-ch-'+id).value!=='custom')$('fs-f-'+id).value=$('fs-ch-'+id).value;safe(draw);};$('fs-f-'+id).onchange=()=>{$('fs-ch-'+id).value='custom';safe(draw);};});action('fs-run',draw);action('fs-add-wall',()=>{if(walls.length>=8)throw Error('Use up to eight walls in this model.');walls.push({distance:read().max/2,loss:5});drawWalls();draw();});action('fs-reset',()=>{walls=[];previousUnit='m';for(const [id,v]of [['fs-unit','m'],['fs-d',8],['fs-axis',30],['fs-mode','loss'],['fs-scale','linear'],['fs-tx',14],['fs-gain',4],['fs-feeder',0]])$(id).value=String(v);bands.forEach(([id,,f])=>{$('fs-ch-'+id).value=String(f);$('fs-f-'+id).value=String(f);});drawWalls();draw();});action('fs-csv',()=>{draw();const headers=['Distance','Unit','Walls crossed',...bands.flatMap(b=>[b[1]+' FSPL dB',b[1]+' Walls dB',b[1]+' Total loss dB',b[1]+' Signal dBm'])];download('wifi-path-loss.csv',headers.join(',')+'\n'+csvRows.map(r=>r.join(',')).join('\n'));});action('fs-png',async()=>{draw();await fsplExportPng(chartMarkup);});drawWalls();draw();}
function fsplChannels(band){const channelNumbers=band==='24'?Array.from({length:14},(_,i)=>i+1):band==='5'?[36,40,44,48,52,56,60,64,100,104,108,112,116,120,124,128,132,136,140,144,149,153,157,161,165]:Array.from({length:59},(_,i)=>1+i*4);return [...channelNumbers.map(ch=>{const f=band==='24'?(ch===14?2484:2407+5*ch):band==='5'?5000+5*ch:5950+5*ch;return [String(f),'Channel '+ch+' · '+f+' MHz'];}),['custom','Custom frequency']];}
function fsplChart(o,walls,bands){const W=820,H=350,left=65,right=25,top=28,bottom=55,min=Math.min(o.factor,o.max/10),x=d=>left+(o.log?Math.log(d/min)/Math.log(o.max/min):(d-min)/(o.max-min))*(W-left-right);const samples=Array.from({length:120},(_,i)=>min*(o.max/min)**(i/119));for(const w of walls)if(w.distance>min&&w.distance<o.max)samples.push(Math.max(min,w.distance*(1-1e-8)),w.distance);samples.sort((a,b)=>a-b);const values=o.freq.map(f=>samples.map(d=>{const r=fsplBudget(f,d,o.tx,o.gain,o.feeder,walls);return o.mode==='loss'?r.total:r.signal;}));let low=Math.floor(Math.min(...values.flat())/10)*10,high=Math.ceil(Math.max(...values.flat())/10)*10;if(low===high)high+=10;const y=v=>H-bottom-(v-low)/(high-low)*(H-top-bottom);let svg='<svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="'+(o.mode==='loss'?'Path loss':'Received signal')+' versus distance for three Wi-Fi bands" viewBox="0 0 '+W+' '+H+'" width="820" height="350" style="width:100%;height:auto;background:#fff;color:#202b32"><title>Wi-Fi path loss comparison</title><rect width="820" height="350" fill="#fff"/>';for(let i=0;i<=5;i++){const v=low+(high-low)*i/5;svg+='<line x1="'+left+'" x2="'+(W-right)+'" y1="'+y(v)+'" y2="'+y(v)+'" stroke="#dde1e4"/><text x="'+(left-8)+'" y="'+(y(v)+4)+'" text-anchor="end" fill="#333" font-size="12">'+v.toFixed(0)+'</text>';}
const ticks=o.log?[min,...[2,4,8,16,32,64,128,256,512,1024].map(v=>v*o.factor).filter(v=>v>min&&v<o.max),o.max]:Array.from({length:6},(_,i)=>min+(o.max-min)*i/5);for(const d of ticks)svg+='<text x="'+x(d)+'" y="'+(H-bottom+22)+'" text-anchor="middle" fill="#333" font-size="12">'+(d/o.factor).toFixed(d/o.factor<1?1:0)+'</text>';walls.forEach((w,i)=>{if(w.distance>=min&&w.distance<=o.max)svg+='<line x1="'+x(w.distance)+'" x2="'+x(w.distance)+'" y1="'+top+'" y2="'+(H-bottom)+'" stroke="#888" stroke-dasharray="3 5"/><text x="'+x(w.distance)+'" y="18" text-anchor="middle" fill="#555" font-size="10">W'+(i+1)+'</text>';});values.forEach((ys,i)=>{svg+='<path d="'+samples.map((d,j)=>(j?'L':'M')+x(d).toFixed(2)+','+y(ys[j]).toFixed(2)).join(' ')+'" fill="none" stroke="'+bands[i][3]+'" stroke-width="2.5"/><text x="'+(left+i*165)+'" y="'+(H-8)+'" fill="'+bands[i][3]+'" font-size="13">'+bands[i][1]+' · '+o.freq[i]+' MHz</text>';});if(o.d>=min&&o.d<=o.max)svg+='<line x1="'+x(o.d)+'" x2="'+x(o.d)+'" y1="'+top+'" y2="'+(H-bottom)+'" stroke="#333" stroke-dasharray="6 4"/>';return svg+'<text x="410" y="'+(H-bottom+39)+'" text-anchor="middle" fill="#333" font-size="12">Distance ('+o.unit+') · '+(o.log?'logarithmic':'linear')+'</text><text x="8" y="15" fill="#333" font-size="12">'+(o.mode==='loss'?'Loss dB':'Signal dBm')+'</text></svg>';}
async function fsplExportPng(markup){const url=URL.createObjectURL(new Blob([markup],{type:'image/svg+xml'}));try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('Unable to render chart export.'));img.src=url;});const canvas=document.createElement('canvas');canvas.width=1640;canvas.height=700;canvas.getContext('2d').drawImage(img,0,0,1640,700);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('Unable to export chart.');const pngUrl=URL.createObjectURL(blob);const a=document.createElement('a');a.href=pngUrl;a.download='wifi-path-loss.png';a.click();setTimeout(()=>URL.revokeObjectURL(pngUrl),1000);}finally{URL.revokeObjectURL(url);}}
